#!/bin/sh
# DEMO ONLY. Fictional timecards, written to a scratch SQLite file under XDG_DATA_HOME. See README.md.
#
# One `find` is the whole program: it digs the directory tree it is walking, one directory per hour,
# and prints SQL as it goes. The three lines around it only seed a scratch folder, feed the SQL to
# sqlite3 and clean up. build-line.py is the readable source of the long expression; check.sh keeps
# the two in step.
set -eu
dir=${XDG_DATA_HOME:-$HOME/.local/share}/FindPosix
mkdir -p "$dir"
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT HUP INT TERM
cd "$work"
mkdir t
{
printf '%s\n' "CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,started_at TEXT);" \
  "CREATE TABLE IF NOT EXISTS demo_timecards(id INTEGER PRIMARY KEY,run_id INTEGER,category TEXT,hours INTEGER CHECK(hours BETWEEN 10 AND 19),running_total INTEGER,iso_week TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,demo_only INTEGER NOT NULL DEFAULT 1 CHECK(demo_only=1));" \
  "CREATE TABLE IF NOT EXISTS stop_rule(ok INTEGER CONSTRAINT \"stop rule fired: total exceeds 40\" CHECK(ok=1));" \
  "INSERT INTO runs(started_at) VALUES(datetime('now','localtime'));" \
  "SELECT printf('# DEMO ONLY run %d',last_insert_rowid());"
find t \( -path 't' -exec printf ' -- ' \; -exec mktemp -d {}/XXXXXX \; \) -o \( -name '??????' -exec printf 'INSERT INTO demo_timecards(run_id,category,hours,running_total,iso_week) VALUES((SELECT max(id) FROM runs),' \; \( \( -path '*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*' -exec printf "'Meetings'," \; \) -o \( -path '*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*' -exec printf "'Learning'," \; \) -o \( -path '*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*' -exec printf "'Debugging'," \; \) -o \( -path '*/[!/][!/][!/][!/][!/][!/]*/[!/][!/][!/][!/][!/][!/]*' -exec printf "'Coding'," \; \) -o \( -exec printf "'Meetings'," \; \) \) \( \( -path '*/0/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/1 \; \) -o \( -path '*/1/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/2 \; \) -o \( -path '*/2/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/3 \; \) -o \( -path '*/3/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/4 \; \) -o \( -path '*/4/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/5 \; \) -o \( -path '*/5/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/6 \; \) -o \( -path '*/6/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/7 \; \) -o \( -path '*/7/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/8 \; \) -o \( -path '*/8/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/9 \; \) -o \( -path '*/9/b00/[!/][!/][!/][!/][!/][!/]' -exec mkdir {}/0 \; \) -o \( -exec mkdir {}/1 \; \) \) \) -o \( -name '?' \( \( -path '*/[!/][!/][!/][!/][!/][abcdef]/?' -exec printf '10,' \; -exec mkdir {}/b09 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][ghijkl]/?' -exec printf '11,' \; -exec mkdir {}/b10 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][mnopqr]/?' -exec printf '12,' \; -exec mkdir {}/b11 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][stuvwx]/?' -exec printf '13,' \; -exec mkdir {}/b12 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][yz0123]/?' -exec printf '14,' \; -exec mkdir {}/b13 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][456789]/?' -exec printf '15,' \; -exec mkdir {}/b14 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][ABCDEF]/?' -exec printf '16,' \; -exec mkdir {}/b15 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][GHIJKL]/?' -exec printf '17,' \; -exec mkdir {}/b16 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][MNOPQR]/?' -exec printf '18,' \; -exec mkdir {}/b17 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][STUVWX]/?' -exec printf '19,' \; -exec mkdir {}/b18 \; \) -o \( -path '*/[!/][!/][!/][!/][abcdef][YZ]/?' -exec printf '10,' \; -exec mkdir {}/b09 \; \) -o \( -path '*/[!/][!/][!/][!/][ghijkl][YZ]/?' -exec printf '11,' \; -exec mkdir {}/b10 \; \) -o \( -path '*/[!/][!/][!/][!/][mnopqr][YZ]/?' -exec printf '12,' \; -exec mkdir {}/b11 \; \) -o \( -path '*/[!/][!/][!/][!/][stuvwx][YZ]/?' -exec printf '13,' \; -exec mkdir {}/b12 \; \) -o \( -path '*/[!/][!/][!/][!/][yz0123][YZ]/?' -exec printf '14,' \; -exec mkdir {}/b13 \; \) -o \( -path '*/[!/][!/][!/][!/][456789][YZ]/?' -exec printf '15,' \; -exec mkdir {}/b14 \; \) -o \( -path '*/[!/][!/][!/][!/][ABCDEF][YZ]/?' -exec printf '16,' \; -exec mkdir {}/b15 \; \) -o \( -path '*/[!/][!/][!/][!/][GHIJKL][YZ]/?' -exec printf '17,' \; -exec mkdir {}/b16 \; \) -o \( -path '*/[!/][!/][!/][!/][MNOPQR][YZ]/?' -exec printf '18,' \; -exec mkdir {}/b17 \; \) -o \( -path '*/[!/][!/][!/][!/][STUVWX][YZ]/?' -exec printf '19,' \; -exec mkdir {}/b18 \; \) -o \( -path '*/[!/][!/][!/][!/][!/][!/]/?' -exec printf '10,' \; -exec mkdir {}/b09 \; \) -o \( -path '*/b18/?' -exec mkdir {}/b17 \; \) -o \( -path '*/b17/?' -exec mkdir {}/b16 \; \) -o \( -path '*/b16/?' -exec mkdir {}/b15 \; \) -o \( -path '*/b15/?' -exec mkdir {}/b14 \; \) -o \( -path '*/b14/?' -exec mkdir {}/b13 \; \) -o \( -path '*/b13/?' -exec mkdir {}/b12 \; \) -o \( -path '*/b12/?' -exec mkdir {}/b11 \; \) -o \( -path '*/b11/?' -exec mkdir {}/b10 \; \) -o \( -path '*/b10/?' -exec mkdir {}/b09 \; \) -o \( -path '*/b09/?' -exec mkdir {}/b08 \; \) -o \( -path '*/b08/?' -exec mkdir {}/b07 \; \) -o \( -path '*/b07/?' -exec mkdir {}/b06 \; \) -o \( -path '*/b06/?' -exec mkdir {}/b05 \; \) -o \( -path '*/b05/?' -exec mkdir {}/b04 \; \) -o \( -path '*/b04/?' -exec mkdir {}/b03 \; \) -o \( -path '*/b03/?' -exec mkdir {}/b02 \; \) -o \( -path '*/b02/?' -exec mkdir {}/b01 \; \) -o \( -path '*/b01/?' -exec mkdir {}/b00 \; \) \) \) -o \( \( -name b00 \( \( -path '*/0/*/0/*/0/*/0/*/0/*' -exec printf '5' \; \) -o \( -path '*/0/*/0/*/0/*/0/*' -exec printf '4' \; \) -o \( -path '*/0/*/0/*/0/*' -exec printf '3' \; \) -o \( -path '*/0/*/0/*' -exec printf '2' \; \) -o \( -path '*/0/*' -exec printf '1' \; \) \) \( \( -path '*/0/b00' -exec printf '0,' \; \) -o \( -path '*/1/b00' -exec printf '1,' \; \) -o \( -path '*/2/b00' -exec printf '2,' \; \) -o \( -path '*/3/b00' -exec printf '3,' \; \) -o \( -path '*/4/b00' -exec printf '4,' \; \) -o \( -path '*/5/b00' -exec printf '5,' \; \) -o \( -path '*/6/b00' -exec printf '6,' \; \) -o \( -path '*/7/b00' -exec printf '7,' \; \) -o \( -path '*/8/b00' -exec printf '8,' \; \) -o \( -path '*/9/b00' -exec printf '9,' \; \) \) -exec date "+'%G-W%V');" \; \( \( -path '*/0/*/0/*/0/*/0/*/0/*' -o \( -path '*/0/*/0/*/0/*/0/*' -path '*/[1-9]/b00' \) \) -o \( -exec printf ' -- ' \; -exec mktemp -d {}/XXXXXX \; \) \) \) -o \( -name 'b??' \( \( -path '*/0/b??' -exec mkdir {}/1 \; \) -o \( -path '*/1/b??' -exec mkdir {}/2 \; \) -o \( -path '*/2/b??' -exec mkdir {}/3 \; \) -o \( -path '*/3/b??' -exec mkdir {}/4 \; \) -o \( -path '*/4/b??' -exec mkdir {}/5 \; \) -o \( -path '*/5/b??' -exec mkdir {}/6 \; \) -o \( -path '*/6/b??' -exec mkdir {}/7 \; \) -o \( -path '*/7/b??' -exec mkdir {}/8 \; \) -o \( -path '*/8/b??' -exec mkdir {}/9 \; \) -o \( -path '*/9/b??' -exec mkdir {}/0 \; \) \) \) \)
printf '%s\n' ".mode tabs" \
  "SELECT category,hours,running_total,iso_week,'DEMO ONLY' FROM demo_timecards WHERE run_id=(SELECT max(id) FROM runs) ORDER BY id;" \
  "SELECT printf('# committed total=%d entries=%d DEMO ONLY',max(running_total),count(*)) FROM demo_timecards WHERE run_id=(SELECT max(id) FROM runs);" \
  "INSERT INTO stop_rule SELECT max(running_total)<=40 FROM demo_timecards WHERE run_id=(SELECT max(id) FROM runs);" \
  "DELETE FROM stop_rule;"
} | sqlite3 "$dir/demo-timecards.db" || :
